for n in names:
    out += [f'ALTER TABLE {n} ENABLE ROW LEVEL SECURITY;',f'CREATE POLICY company_isolation ON {n} USING(company_id=company_uuid()) WITH CHECK(company_id=company_uuid());',f'CREATE INDEX {n}_company_created ON {n}(company_id,created_at);']
for n in ['inventory_movements','customer_transactions','supplier_transactions','payment_allocations','cash_movements','tax_transactions','approval_decisions','cost_layer_allocations']:
    out += [f'CREATE TRIGGER {n}_immutable BEFORE UPDATE OR DELETE ON {n} FOR EACH ROW EXECUTE FUNCTION deny_mutation();']
for n in ['customers','suppliers','products']:
    out += [f'CREATE INDEX {n}_name_search ON {n} USING gin(name gin_trgm_ops);']
out += ['COMMIT;']
Path('db/002-domains.sql').write_text('\n\n'.join(out)+'\n')
Path('docs/table-inventory.txt').write_text('\n'.join(names)+'\n')
print(f'Generated {len(names)} target domain tables')
